    originalLife(p, world) &&
    p.lifeDescriptor.get!.call(p.life) === false &&
    demonJson(p.privateState) === originalJson &&
    writableDemonFields(state, ["canShoot"]);
  return Object.freeze({
    isCurrent,
    consume: () => {
      if (
        committed ||
        !validBinding(b) ||
        !originalLife(p, world) ||
        p.lifeDescriptor.get!.call(p.life) !== false ||
        demonJson(p.privateState) !== originalJson ||
        !writableDemonFields(state, ["canShoot"])
      )
        throw new Error("demon_hunter_native_hunter_stock_revoked");
      (state as Record<string, unknown>).canShoot = false;
      const json = JSON.stringify({ ...original, hunter: { ...hunter, canShoot: false } });
      if (demonJson(p.privateState) !== json)
        throw new Error("demon_hunter_native_hunter_commit_failed");
      committed = true;
      p.auditPrivateJson = json;
    },
  });
}

/** 失败周期中即使外来代码替换对象，仍保留原阵容及已提交库存。 */
export function demonHunterCheckpointPlayers(world: World, complete: boolean) {
  const b = bindings.get(world);
  if (!b) return null;
  if (
    complete &&
    (!validBinding(b) ||
      ![...b.players.values()].every((p) => originalLife(p, world) && privateAuditCurrent(b, p)))
  )
    throw new Error("demon_hunter_checkpoint_original_state_revoked");
  return [...b.players.values()].map((p) => {
    const cp = p.checkpoint;
    if (!cp) throw new Error("demon_hunter_checkpoint_metadata_missing");
    const currentBadge = demonBadgeJson(cp.badge),
      currentVote = demonVoteJson(cp.vote);
    const originalMetadata =
      world.getComponent(p.id, COMPONENT.Identity) === cp.identity &&
      ownDemonData(cp.identity, "seat") === cp.seat &&
      ownDemonData(cp.identity, "name") === cp.name &&
      world.getComponent(p.id, COMPONENT.Badge) === cp.badge &&
      world.getComponent(p.id, COMPONENT.VotingRight) === cp.vote &&
      world.getComponent(p.id, COMPONENT.StatusMarks) === cp.marks;
    const marks = Object.values(StatusMark).map(
      (mark) => [mark, statusMarkSnapshot(cp.marks, mark)] as const,
    );
    if (complete) {
      if (
        !originalMetadata ||
        !currentBadge ||
        !currentVote ||
        currentBadge !== cp.badgeJson ||
        currentVote !== cp.voteJson ||
        marks.some(([, snapshot]) => !snapshot)
      )
        throw new Error("demon_hunter_checkpoint_metadata_revoked");
    }
    return {
      id: p.id,
      seat: cp.seat,
      name: cp.name,
      role: p.kind,
      camp: p.camp,
      alive: p.lifeDescriptor.get!.call(p.life) === true,
      privateState: committedPrivate(b, p, complete),
      victory: { affiliations: JSON.parse(p.victoryJson) as VictoryComponent["affiliations"] },
      vote: JSON.parse(cp.voteJson) as { weight: number; canVote: boolean },
      badge: JSON.parse(cp.badgeJson) as {
        isSheriff: boolean;
        destroyed: boolean;
        voteWeight: number;
        handoffPolicy?: import("../../../../core/domain/board").SheriffBadgePolicy;
      },
      marks: marks.flatMap(([mark, snapshot]) => (snapshot?.present ? [mark] : [])),
    };
  });
}

/** 权限回调在任何旧枪政策／状态读取前检查 descriptor。 */
export function demonHunterNativeGunCurrent(world: World, actorId: number): boolean {
  const b = bindings.get(world);
  if (!b) return true;
  const p = b.players.get(actorId);
  return (
    !!p &&
    p.kind === Role.Hunter &&
    validBinding(b) &&
    originalLife(p, world) &&
    p.lifeDescriptor.get!.call(p.life) === false &&
    privateAuditCurrent(b, p)
  );
}

/** 有限板子的警徽写入在实际同步提交时缓存，不在失败 checkpoint 中刷新。 */
export function openDemonBadgeFrame(world: World): Readonly<{
  commit: (
    change:
      | { kind: "assign"; sheriffId: number; weight: number; policy: string | undefined }
      | {
          kind: "handoff";
          fromId: number;
          toId: number | null;
          weight: number;
          policy: string | undefined;
        },
  ) => void;
}> | null {
  const b = bindings.get(world);
  if (!b) return null;
  if (!validBinding(b)) throw new Error("demon_hunter_badge_original_state_revoked");
  const before = new Map(
    [...b.players.values()].map((p) => {
      const cp = p.checkpoint;
      if (
        !cp ||
        world.getComponent(p.id, COMPONENT.Badge) !== cp.badge ||
        world.getComponent(p.id, COMPONENT.VotingRight) !== cp.vote ||
        !originalLife(p, world) ||
        demonBadgeJson(cp.badge) !== cp.badgeJson ||
        demonVoteJson(cp.vote) !== cp.voteJson ||
        !writableDemonFields(cp.badge, ["isSheriff", "destroyed", "voteWeight"]) ||
        !writableDemonFields(cp.vote, ["weight"]) ||
        !Object.isExtensible(cp.badge) ||
        Object.getOwnPropertyDescriptor(cp.badge, "handoffPolicy")?.configurable === false
      )
        throw new Error("demon_hunter_badge_stock_revoked");
      return [
        p.id,
        {
          cp,
          badge: JSON.parse(cp.badgeJson),
          vote: JSON.parse(cp.voteJson),
          alive: p.lifeDescriptor.get!.call(p.life) === true,
        },
      ] as const;
    }),
  );
  let committed = false;
  return Object.freeze({
    commit: (change) => {
      if (
        committed ||
        !validBinding(b) ||
        change.weight !== 1.5 ||
        change.policy !== (b.config.nobleSecretBody ? "awa_holder_choice_v1" : undefined)
      )
        throw new Error("demon_hunter_badge_commit_invalid");
      const expected = new Map(
        [...before].map(([id, item]) => [id, { badge: { ...item.badge }, vote: { ...item.vote } }]),
      );
      if (change.kind === "assign") {
        if (!before.get(change.sheriffId)?.alive)
          throw new Error("demon_hunter_badge_commit_invalid");
        for (const [id, item] of before)
          if (item.alive) {
            const next = expected.get(id)!;
            next.badge.isSheriff = id === change.sheriffId;
            next.badge.destroyed = false;
            next.badge.voteWeight = change.weight;
            if (change.policy) next.badge.handoffPolicy = change.policy;
            else delete next.badge.handoffPolicy;
            if (next.vote.canVote) next.vote.weight = id === change.sheriffId ? change.weight : 1;
          }
      } else {
        const from = expected.get(change.fromId);
        if (
          !from ||
          !from.badge.isSheriff ||
          from.badge.destroyed ||
          change.toId === change.fromId ||
          (change.toId !== null && !before.get(change.toId)?.alive)
        )
          throw new Error("demon_hunter_badge_commit_invalid");
        from.badge.isSheriff = false;
        from.badge.destroyed = true;
        from.vote.weight = from.vote.canVote ? 1 : 0;
        if (change.toId !== null) {
          const next = expected.get(change.toId)!;
          next.badge.isSheriff = true;
          next.badge.destroyed = false;
          next.badge.voteWeight = change.weight;
          if (change.policy) next.badge.handoffPolicy = change.policy;
          else delete next.badge.handoffPolicy;
          next.vote.weight = change.weight;
        }
      }
      for (const [id, next] of expected) {
        const cp = before.get(id)!.cp;
        if (
          world.getComponent(id, COMPONENT.Badge) !== cp.badge ||
          world.getComponent(id, COMPONENT.VotingRight) !== cp.vote ||
          demonBadgeJson(cp.badge) !== JSON.stringify(next.badge) ||
          demonVoteJson(cp.vote) !== JSON.stringify(next.vote)
        )
          throw new Error("demon_hunter_badge_commit_revoked");
      }
      committed = true;
      for (const [id, next] of expected) {
        const cp = before.get(id)!.cp;
        cp.badgeJson = JSON.stringify(next.badge);
        cp.voteJson = JSON.stringify(next.vote);
      }
    },
  });
}

/** 原生警徽可选 metadata 必须区分缺失与被拒绝的 accessor。 */
export function assertDemonBadgeReadable(world: World): void {
  const b = bindings.get(world);
  if (!b) return;
  for (const p of b.players.values()) {
    const cp = p.checkpoint;
    if (!cp) continue;
    if (
      world.getComponent(p.id, COMPONENT.Badge) !== cp.badge ||
      world.getComponent(p.id, COMPONENT.VotingRight) !== cp.vote ||
      !demonBadgeJson(cp.badge) ||
      !demonVoteJson(cp.vote)
    )
      throw new Error("demon_hunter_badge_unreadable");
  }
}

export function demonNativeNightActor(
  world: World,
  kind: "seer_check" | "guard",
): { actorId: number; ability: object } | null {
  const b = bindings.get(world),
    n = b?.active;
  if (!b || !n || n.closed || n.frozen || !validBinding(b))
    throw new Error("demon_hunter_native_night_unavailable");
  const p = [...b.players.values()].find(
    (p) => p.kind === (kind === "seer_check" ? Role.Seer : Role.Guard),
  );
  if (!p || !n.targets.has(p.id) || demonRedMoonNightSealed(world, n.day)) return null;
  const ability = ownDemonData(ownDemonData(p.privateState, "abilities"), `native:${kind}`);
  if (!ability || typeof ability !== "object")
    throw new Error("demon_hunter_native_night_unavailable");
  return { actorId: p.id, ability };
}

/** 原生红月状态的有限审计转换，不采用任意 live 库存。 */
export function commitDemonRedMoonTransition(
  world: World,
  actorId: number,
  kind: "blast" | "exile" | "expire",
  day: number,
): boolean {
  const b = bindings.get(world),
    p = b?.players.get(actorId);
  const n = kind === "expire" ? b?.active : b?.nights.get(day);
  if (
    !b ||
    !p ||
    !n ||
    n.day !== day ||
    !validBinding(b) ||
    String(p.kind) !== RED_MOON_ROLE ||
    ![...b.players.values()].every((player) => originalLife(player, world)) ||
    !privateAuditCurrent(b, p)
  )
    return false;
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state || !writableDemonFields(state, ["blastDay", "exileDay", "expirySettled"]))
    return false;
  // 本族编码函数只消费已捕获的影子；解析查找先于 audit 字段读取，原体／夜权限仍留在这里。
  const original = readRedMoonShadow(() => p.auditPrivateJson);
  const next = copyRedMoonPayload(state);
  if (kind === "expire") {
    if (n.closed || !n.frozen || state.exileDay !== day - 1 || state.expirySettled) return false;
    next.expirySettled = true;
  } else {
    if (
      b.active ||
      !n.closed ||
      !n.frozen ||
      [...b.nights.keys()].some((d) => d > day) ||
      !originalLife(p, world, true) ||
      state.blastDay !== null ||
      state.exileDay !== null
    )
      return false;
    const wolves = [...b.players.values()].filter(
      (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
    ).length;
    if (kind === "blast") {
      if (wolves === 1 && state.lastWolfBlastPolicy === "forbidden") return false;
      next.blastDay = day;
    } else if (kind === "exile") {
      if (wolves !== 1) return false;
      next.exileDay = day;
    } else return false;
  }
  const expected = encodeRedMoonShadow(original, next);
  // 三写只归本族 slot；完整容器验收和 audit 最终更新保持原点，后续失败不撤销先前字段。
  writeRedMoonTransition(state, next);
  if (demonJson(p.privateState) !== expected) throw new Error("red_moon_state_commit_failed");
  p.auditPrivateJson = expected;
  return true;
}

/** 原红月自爆只抑制紧接的下一夜好人行动。 */
export function demonRedMoonNightSealed(world: World, day: number): boolean {
  const b = bindings.get(world);
  if (!b) return false;
  const p = [...b.players.values()].find((p) => String(p.kind) === RED_MOON_ROLE);
  if (!p) return false;
  if (!validBinding(b) || ![...b.players.values()].every((p) => originalLife(p, world)))
    throw new Error("red_moon_original_state_revoked");
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state || !privateAuditCurrent(b, p)) throw new Error("red_moon_original_state_revoked");
  const sealed = Number.isSafeInteger(day) && day > 1 && state.blastDay === day - 1;
  if (sealed && originalLife(p, world, true)) throw new Error("red_moon_blast_death_unsettled");
  return sealed;
}

/** 有限板子的白痴翻牌时，同时保留私有库存与公开票权审计。 */
export function commitDemonIdiotReveal(world: World, actorId: number): boolean {
  const b = bindings.get(world);
  if (!b) return false;
  const p = b.players.get(actorId),
    cp = p?.checkpoint;
  if (
    !p ||
    !cp ||
    p.kind !== Role.Idiot ||
    !validBinding(b) ||
    !originalLife(p, world, true) ||
    !privateAuditCurrent(b, p) ||
    world.getComponent(actorId, COMPONENT.VotingRight) !== cp.vote ||
    demonVoteJson(cp.vote) !== cp.voteJson ||
    !writableDemonFields(p.privateState, ["idiot"]) ||
    !writableDemonFields(cp.vote, ["canVote", "weight"])
  )
    throw new Error("demon_hunter_idiot_state_revoked");
  const before = ownDemonData(p.privateState, "idiot");
  if (!exactDemonData(before, ["revealed"]) || ownDemonData(before, "revealed") !== false)
    throw new Error("demon_hunter_idiot_state_revoked");
  // 消耗翻牌前先验证后续同步警徽交接。
  openDemonBadgeFrame(world);
  const next = { revealed: true };
  const original = JSON.parse(p.auditPrivateJson) as Record<string, unknown>;
  const expectedPrivate = JSON.stringify({ ...original, idiot: next });
  const expectedVote = JSON.stringify({ ...JSON.parse(cp.voteJson), canVote: false, weight: 0 });
  (p.privateState as { idiot: typeof next }).idiot = next;
  (cp.vote as VotingRightComponent).canVote = false;
  (cp.vote as VotingRightComponent).weight = 0;
  if (demonJson(p.privateState) !== expectedPrivate || demonVoteJson(cp.vote) !== expectedVote)
    throw new Error("demon_hunter_idiot_commit_failed");
  p.privateRefs = p.privateRefs.map(
    ([key, value]) => [key, key === "idiot" ? next : value] as const,
  );
  p.inventoryRefs = p.inventoryRefs.map(
    ([path, value]) => [path, path.length === 1 && path[0] === "idiot" ? next : value] as const,
  );
  p.auditPrivateJson = expectedPrivate;
  cp.voteJson = expectedVote;
  return true;
}

/** 在任何旧状态 getter 可执行前读取已提交的白痴状态。 */
export function demonIdiotRevealed(world: World, actorId: number): boolean | null {
  const b = bindings.get(world);
  if (!b) return null;
  const p = b.players.get(actorId),
    cp = p?.checkpoint;
  if (
    !p ||
    !cp ||
    p.kind !== Role.Idiot ||
    !validBinding(b) ||
    !originalLife(p, world, true) ||
    !privateAuditCurrent(b, p) ||
    world.getComponent(actorId, COMPONENT.VotingRight) !== cp.vote ||
    demonVoteJson(cp.vote) !== cp.voteJson
  )
    throw new Error("demon_hunter_idiot_state_revoked");
  const state = ownDemonData(p.privateState, "idiot");
  const revealed = ownDemonData(state, "revealed");
  if (!exactDemonData(state, ["revealed"]) || typeof revealed !== "boolean")
    throw new Error("demon_hunter_idiot_state_revoked");
  return revealed;
}

/** 有限板子当前日只由最近已结算的夜产生。 */
export function demonRedMoonDay(world: World, actorId: number): number | null {
  const b = bindings.get(world),
    p = b?.players.get(actorId);
  if (!b || !p || String(p.kind) !== RED_MOON_ROLE) return null;
  demonHunterCheckpointPlayers(world, true);
  if (b.active || !originalLife(p, world, true)) return null;
  const day = [...b.nights.keys()].at(-1);
  const n = day === undefined ? null : b.nights.get(day);
  return n?.closed && n.frozen ? n.day : null;
}
export function demonRedMoonCanBlast(world: World, actorId: number): boolean {
  if (demonRedMoonDay(world, actorId) === null) return false;
  const b = bindings.get(world)!,
    p = b.players.get(actorId)!;
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state || state.blastDay !== null || state.exileDay !== null) return false;
  const wolves = [...b.players.values()].filter(
    (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
  ).length;
  return wolves > 1 || state.lastWolfBlastPolicy === "ends_game";
}
export function commitDemonRedMoonBlast(
  world: World,
  actorId: number,
): { day: number; sealsNight: boolean } | null {
  const day = demonRedMoonDay(world, actorId);
  if (day === null || !demonRedMoonCanBlast(world, actorId)) return null;
  const b = bindings.get(world)!;
  const wolves = [...b.players.values()].filter(
    (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
  ).length;
  if (!commitDemonRedMoonTransition(world, actorId, "blast", day)) return null;
  return { day, sealsNight: wolves > 1 };
}

/** 被延后的存活最后一狼只在普通来源已结算后到期。 */
export function demonRedMoonExpiry(world: World, day: number): number | null {
  const b = bindings.get(world);
  if (!b) return null;
  const p = [...b.players.values()].find((player) => String(player.kind) === RED_MOON_ROLE);
  if (!p) return null;
  demonHunterCheckpointPlayers(world, true);
  const n = b.active;
  if (!n || n.day !== day || n.closed || !n.frozen)
    throw new Error("red_moon_expiry_phase_invalid");
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state) throw new Error("red_moon_original_state_revoked");
  return state.exileDay === day - 1 && !state.expirySettled && originalLife(p, world, true)
    ? p.id
    : null;
}

export function isRedMoonBoard(world: World): boolean {
  const b = bindings.get(world);
  if (!b || ![...b.players.values()].some((p) => p.kind === Role.RedMoonApostle)) return false;
  if (!validBinding(b)) throw new Error("red_moon_original_state_revoked");
  return true;
}

controls.text:
/**
 * 负责猎魔人完整数据槽：原 schema／工具副本、creator、同引用查询、安装及已接受历史写入。
 * 输入为原角色或 authority 的原 state／history／夜时钟；输出保持 live 引用和唯一 historyJson。
 * Node 快照只在原入口拒绝外来 descriptor／Proxy，校验副本不替换运行槽；公共纯结构仍归契约包。
 * 原下一历史先编码，再 push 和更新 JSON；后续 actor 审计、夜选择、请求结算和 stock 写权仍归 authority。
 * 此 owner 不建镜像／第二 WeakMap、不冻结 live 数据或把类型／查询当许可；失败保原部分写入前缀。
 */
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core";
import { DEMON_HUNTER_POLICY, readDemonHunterState as readState, readDemonHuntTool as readTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import type { DemonHunterState, DemonHuntTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
export { DEMON_HUNTER_POLICY };
export const DEMON_HUNTER_ROLE = "demon_hunter" as const;
export function ownDemonData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}
export function demonSnapshot(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
): unknown {
  return snapshotPlainData(value, seen, depth, arrayLimit, "demon_hunter_data_invalid");
}
export function demonJson(value: unknown): string | null {
  try {
    return JSON.stringify(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function exactDemonData(
  value: unknown,
  keys: readonly string[],
): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}
export function freshDemonHunterState(): DemonHunterState {
  return { policy: DEMON_HUNTER_POLICY, history: [] };
}
export function readDemonHunterState(value: unknown): DemonHunterState | null {
  try {
    return readState(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function getDemonHunterState(role: RoleComponent | undefined): DemonHunterState | undefined {
  const s = ownDemonData(ownDemonData(role, "privateState"), "demonHunter");
  // 复制只用于验证；成功后仍返回原 slot，不能让查询生成第二份 live 状态。
  return readDemonHunterState(s) ? (s as DemonHunterState) : undefined;
}
export function readDemonHuntTool(value: unknown): DemonHuntTool | null {
  try {
    return readTool(demonSnapshot(value));
  } catch {
    return null;
  }
}

/** 唯一 live state／history 和已提交 JSON 留在原 binding 对象，不复制第二份运行库存。 */
export interface DemonHunterStateSlot {
  state: DemonHunterState;
  history: DemonHunterState["history"];
  historyJson: string;
}

/** 初始化仍先求值左侧 privateState，再调用原 creator；没有 schema、授权或新冻结。 */
export function installDemonHunterStateSlot(role: RoleComponent): void {
  (role.privateState as { demonHunter: DemonHunterState }).demonHunter = freshDemonHunterState();
}

/** 原安装字段依次取 state、history，再给空历史 JSON；临时返回对象不成为第二份 live store。 */
export function captureDemonHunterStateSlot(state: DemonHunterState): DemonHunterStateSlot {
  return { state, history: state.history, historyJson: "[]" };
}

/** 数据当前性保持原历史引用优先、已校验历史 JSON 后查；原参与者与 World alias 仍由 authority 核对。 */
export function demonHunterHistoryCurrent(b: DemonHunterStateSlot, state: DemonHunterState): boolean {
  return ownDemonData(b.state, "history") === b.history && demonJson(state.history) === b.historyJson;
}

/**
 * 完整原历史写命令。各 history 与 n.day 均在原表达式处读取；不提前缓存夜时钟。
 * 下一历史 JSON 失败时尚未 push；push 后再写 historyJson，后续抛错保留原历史写入前缀。
 * 返回原冻结 choice；actor.auditPrivateJson、n.choice／turn 和请求结算必须仍由 authority 随后按原序提交。
 */
export function appendDemonHunterChoiceData(
  b: DemonHunterStateSlot,
  n: { readonly day: number },
  targetId: number | null,
): Readonly<DemonHunterState["history"][number]> | null {
  const length = Object.getOwnPropertyDescriptor(b.history, "length");
  if (!length?.writable || !Object.isExtensible(b.history) || (b.history.at(-1)?.day ?? 1) >= n.day)
    return null;
  const choice = Object.freeze({ day: n.day, targetId });
  const nextHistoryJson = demonJson([...b.history, choice]);
  if (nextHistoryJson === null) return null;
  b.history.push(choice);
  b.historyJson = nextHistoryJson;
  return choice;
}

/**
 * 负责赤月使徒的完整数据槽：原初态、五字段校验、同引用读取、玩家投影及三项有序提交。
 * 输入为原角色、原状态和调用方已经捕获的审计数据；输出保留原引用或原 JSON／浅副本，
 * 不改变旧接受集合。属性描述符校验允许原非枚举／只读数据字段，可写资格另由权威核对。
 * 状态提交只写 blastDay、exileDay、expirySettled；后项失败保留前项写入，不回滚或重读角色槽。
 * 内部审计编码函数 保留完整容器字段和 JSON 方法的原查找时点，不是严格档案读器 或复现授权。
 * 原生命、末狼、夜窗口、请求租约和完整容器失效／最终审计写入仍由恶魔猎手权威持有。
 * 角色阵营渠道已退出；reader／project 以显式晚读 CurrentCampSource 获取实际 Camp，原 raw schema／写者不因此获得许可。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import type {
  LastWolfBlastPolicy,
  RedMoonState,
  RedMoonReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent } from "../contracts";
import { Camp } from "../../../../core/domain/identity";

export const RED_MOON_ROLE = "red_moon_apostle" as const;
export const RED_MOON_POLICY = "awa_red_moon_demon_v1" as const;
function own(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : undefined;
}
function day(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
export function freshRedMoonState(
  lastWolfBlastPolicy: LastWolfBlastPolicy = "ends_game",
): RedMoonState {
  return {
    policy: RED_MOON_POLICY,
    lastWolfBlastPolicy,
    blastDay: null,
    exileDay: null,
    expirySettled: false,
  };
}
/** 安装的左值先查原 privateState，再在原 fresh callee 后读取政策；初始化不复制或二次校验。 */
export function initializeRedMoonState(
  role: RoleInitializationComponent,
  readPolicy: () => LastWolfBlastPolicy,
): void {
  role.privateState.redMoon = freshRedMoonState(readPolicy());
}

/** 原五字段形状校验 返回输入本体；拒绝代理对象／访问器，不执行它们，也不补默认或加强可写要求。 */
export function readRedMoonPayload(state: unknown): RedMoonReadState | undefined {
  if (!state || typeof state !== "object" || types.isProxy(state)) return undefined;
  const expected = ["policy", "lastWolfBlastPolicy", "blastDay", "exileDay", "expirySettled"];
  const fields = Object.getOwnPropertyDescriptors(state);
  if (
    Reflect.ownKeys(fields).length !== expected.length ||
    !expected.every((key) => fields[key] && "value" in fields[key]!)
  )
    return undefined;
  const policy = own(state, "lastWolfBlastPolicy");
  const blast = own(state, "blastDay"),
    exile = own(state, "exileDay");
  const settled = own(state, "expirySettled");
  if (
    own(state, "policy") !== RED_MOON_POLICY ||
    (policy !== "ends_game" && policy !== "forbidden") ||
    (blast !== null && !day(blast)) ||
    (exile !== null && !day(exile)) ||
    (blast !== null && exile !== null) ||
    typeof settled !== "boolean" ||
    (settled && exile === null)
  )
    return undefined;
  return state as RedMoonReadState;
}

/** 原角色／阵营门槛先于容器与 payload 校验；不以合法副本替换所属 live 状态。 */
// 当前阵营只在原 camp 数据读取点取得；保本族自身 descriptor／Proxy 策略，不回退角色或目录。
export function getRedMoonState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): RedMoonReadState | undefined {
  if (own(role, "role") !== RED_MOON_ROLE || own(currentCamp(), "camp") !== Camp.Wolf) return undefined;
  const state = own(own(role, "privateState"), "redMoon");
  return readRedMoonPayload(state);
}

/** 机制自己决定玩家字段；校验失败仍为 undefined，不补默认政策或猜测到期结果。 */
export function projectRedMoonState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): RedMoonState | undefined {
  const redMoon = getRedMoonState(role, currentCamp);
  if (redMoon)
    return {
      policy: redMoon.policy,
      lastWolfBlastPolicy: redMoon.lastWolfBlastPolicy,
      blastDay: redMoon.blastDay,
      exileDay: redMoon.exileDay,
      expirySettled: redMoon.expirySettled,
    };
}

/** JSON.parse 的方法查找先于 readJson；只解码原已持有审计字符串，不读取 live 容器。 */
export function readRedMoonShadow(readJson: () => string): Record<string, unknown> {
  return JSON.parse(readJson()) as Record<string, unknown>;
}

/** 在原状态校验后按原 spread 顺序生成候选；这是一次浅副本，不是第二份 live 库存。 */
export function copyRedMoonPayload(state: RedMoonReadState): RedMoonState {
  return { ...state };
}

/** 原完整私有容器保留其余字段；JSON.stringify 查找先于 spread，结果只供原同步审计比较。 */
export function encodeRedMoonShadow(original: Record<string, unknown>, next: RedMoonState): string {
  return JSON.stringify({ ...original, redMoon: next });
}

/** 调用方已完成原可写预检与 kind／夜政策；每次 next 字段读取仍紧邻对应写入，失败不补偿。 */
export function writeRedMoonTransition(state: RedMoonReadState, next: RedMoonState): void {
  (state as Pick<RedMoonState, "blastDay">).blastDay = next.blastDay;
  (state as Pick<RedMoonState, "exileDay">).exileDay = next.exileDay;
  (state as Pick<RedMoonState, "expirySettled">).expirySettled = next.expirySettled;
}

/**
 * 契约引用本族唯一实现；仅冻结声明，不冻结原运行状态。形状校验和失效读取沿用同一原校验，
 * 不新增 id／life／request 租约。checkpoint 是内部审计影子的原编码函数，未替代档案完整读器。
 */
export const RED_MOON_STATE_SLOT = Object.freeze({
  create: freshRedMoonState,
  schema: readRedMoonPayload,
  get: getRedMoonState,
  install: initializeRedMoonState,
  allowedWrites: Object.freeze({ transition: writeRedMoonTransition }),
  checkpoint: Object.freeze({
    read: readRedMoonShadow,
    prepare: copyRedMoonPayload,
    encode: encodeRedMoonShadow,
  }),
  invalidations: Object.freeze({ readCurrent: getRedMoonState }),
});

/**
 * 负责 checkpoint 玩家记录的有序编码。输入为同一 World、完整／失败模式和最初动物审计快照；
 * 输出保留恶魔原体优先；私有状态由数据 owner 在原字段位置编码，其余完整字段和顺序仍归本装配。
 * 原体 descriptor、JSON、重复组件读取和 fallback 克隆各在原表达式处执行；不修改 live 状态。
 * 壁上便签、恋人、处罚、胜利、投票、警徽和印记贡献只编码，不推导新规则或授予行动权限。
 */
import {
  COMPONENT,
  type BadgeComponent,
  type IdentityComponent,
  type RoleComponent,
  type StatusMarksComponent,
  type VotingRightComponent,
  type VictoryComponent,
  type World,
} from "../../core";
import type { RecordedCheckpoint } from "../reproduction";
import type { prepareAnimalCheckpoint } from "./authority-snapshots";
import { auditData } from "./animal-audit";
import { encodeCheckpointPrivateState } from "./private-state-codec";
import { aliveLifeDescriptor } from "../../core/domain/components/alive";
import {
  animalOriginalAuditPlayer,
  animalOriginalAuditIds,
} from "../../game/mechanisms/roles/animal_dream/roster";
import { demonHunterCheckpointPlayers } from "../../game/mechanisms/roles/demon_hunter/authority";
import { weddingAuditPlayer } from "../../game/mechanisms/roles/ghost_bride/authority";
import {
  projectLonelyGirlVictory,
  projectLonelyGirlAuditPlayer,
} from "../../game/mechanisms/roles/lonely_girl/lifecycle";
import { projectWallNote } from "../../game/mechanisms/events/wall_notes/authority";

/** 同一调用按原权威优先级编码；数据可供归档核验，不能替代运行时原体或库存许可。 */
export function capturePlayerContributions(
  world: World,
  complete: boolean,
  animal: ReturnType<typeof prepareAnimalCheckpoint>,
): RecordedCheckpoint["players"] {
  return (
    // 恶魔板的完整原参与者快照优先返回；非 null 时不读取后面的席位名单或其它贡献。
    demonHunterCheckpointPlayers(world, complete) ??
    (animalOriginalAuditIds(world) ?? world.entityIds()).map((id) => {
      // 动物失败审计保留最初授权身体；身份／票权／警徽从捕获数据解码，普通路径才读取当前组件。
      const original = animal ? animalOriginalAuditPlayer(world, id) : null;
      const identity = original
        ? (JSON.parse(original.identityJson) as IdentityComponent)
        : world.getComponent(id, COMPONENT.Identity)!;
      const role = original?.scope.role ?? world.getComponent(id, COMPONENT.Role)!;
      const badge = original
        ? (auditData(original.audit.badge, [
            "isSheriff",
            "destroyed",
            "voteWeight",
            "handoffPolicy",
          ]) as BadgeComponent)
        : world.getComponent(id, COMPONENT.Badge)!;
      const vote = original
        ? (auditData(original.audit.vote, ["weight", "canVote"]) as VotingRightComponent)
        : world.getComponent(id, COMPONENT.VotingRight)!;
      const weddingAudit = weddingAuditPlayer(world, id, !complete);
      // 婚约审计优先于孤女审计；记录覆盖与历史Camp保原优先级，普通fallback才晚读实际Camp。
      const audit = weddingAudit ?? projectLonelyGirlAuditPlayer(world, id);
      const wall = projectWallNote(world, id);
      const wallNote = wall
        ? {
            instanceId: wall.instanceId,
            source: { ...wall.source },
            remaining: wall.remaining,
            expired: wall.expired,
          }
        : undefined;
      return {
        id,
        seat: identity.seat,
        name: identity.name,
        role: (original?.scope.roleId as RoleComponent["role"]) ?? audit?.role ?? role.role,
        camp: original?.scope.campValue ?? audit?.camp ?? world.getComponent(id, COMPONENT.Camp)!.camp,
        alive: original
          ? aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life)
          : (audit?.alive ?? world.getComponent(id, COMPONENT.Alive)!.alive),
        // 原特殊审计优先级与整容器克隆归数据 owner；这里只在原字段位置传入已求出的引用。
        privateState: encodeCheckpointPrivateState(world, id, complete, animal, original, role, audit),
        ...(wallNote ? { wallNote } : {}),
        // 可选组件先判断、再现场读取并克隆；getter／克隆失败仍从原表达式传播，不补空记录。
        ...(world.getComponent(id, COMPONENT.DebatePenalty)
          ? {
              debatePenalty: structuredClone(world.getComponent(id, COMPONENT.DebatePenalty)!),
            }
          : {}),
        ...(world.getComponent(id, COMPONENT.Lovers)
          ? {
              lovers: structuredClone(world.getComponent(id, COMPONENT.Lovers)!),
            }
          : {}),
        // 原动物、婚约及孤女胜利记录先于普通组件克隆；失败审计和当前成功记录不可互换来源。
        victory:
          (original ? (JSON.parse(original.victoryJson) as VictoryComponent) : null) ??
          (weddingAudit ? { affiliations: weddingAudit.victory } : null) ??
          projectLonelyGirlVictory(world, id) ??
          structuredClone(world.getComponent(id, COMPONENT.Victory)!),
        vote: { weight: vote.weight, canVote: vote.canVote },
        badge: {
          isSheriff: badge.isSheriff,
          destroyed: badge.destroyed,
          voteWeight: badge.voteWeight,
          ...(badge.handoffPolicy ? { handoffPolicy: badge.handoffPolicy } : {}),
        },
        marks: (
          (original?.audit.marks as StatusMarksComponent | undefined) ??
          world.getComponent(id, COMPONENT.StatusMarks)!
        ).values(),
      };
    })
  );
}

/**
 * 负责有限猎魔人板的原生女巫行动、真实用药交付及夜间来源封存。
 * 输入为原 World、夜号、刀口、网关与 Provider；输出为行动回执、已付救／毒交付及封存来源。
 * 两条原毒分支在原 claim 创建位置附加 sourced intent，复用已捕获 source/target/day。
 * 保留瓶数付款、commit、交付缓存、事实发布与关闭的原次序；后续失败不回滚已提交前缀。
 * 新来源 metadata 与 life 句柄仅运行时使用，不加入事件、player DTO 或归档字段。
 */
import {
  COMPONENT,
  Phase,
  PotionType,
  StatusMark,
  settleRequestDelivery,
  type ActionProvider,
  type GameEvent,
  type World,
} from "../../../../core";
import {
  StatusMarksComponent,
  statusMarkSnapshot,
} from "../../../../core/domain/components/status_marks";
import {
  captureNightLife,
  originalPoisonIntent,
  type NightPoisonClaim,
} from "../../../../core/domain/night_effects";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { recordNightAbilityUse, type NightAbility } from "../abilities";
import {
  openDemonWitchTurnFrame,
  demonHunterFreezeDay,
  demonWitchRequiredThisNight,
} from "./authority";
import {
  bindDemonWitchRequest,
  demonWitchRequestCurrent,
  readDemonPotionTool,
  demonWitchRequestTargetCurrent,
  demonWitchMarksSafe,
} from "./native_potion_requests";
import {
  captureDemonNativePoison,
  commitDemonNativePoison,
  freezeDemonNightSources,
  type DemonNightSources,
} from "./native_poison";
import {
  openNativePoisonContribution,
  commitNativePoisonContribution,
  sealNativePoisonContribution,
  lateUnknownPoisonContribution,
  type NativePoisonContributions,
} from "./poison_contribution";

import {
  openNativeHealContribution,
  commitNativeHealContribution,
  sealNativeHealContribution,
  lateUnknownHealContribution,
  type NativeHealContributions,
} from "./heal_contribution";
/** 已付救药的运行交付；原生命查询与贡献封存回调不能进入玩家 DTO 或归档。 */
interface DeliveredDemonHeal {
  readonly claim: Readonly<NightPoisonClaim>;
  readonly lateUnknown: () => boolean;
  readonly sealContribution: () => Readonly<NativeHealContributions>;
}
const deliveredHeals = new WeakMap<World, Map<number, Readonly<DeliveredDemonHeal>>>();
/**
 * 已付原生毒的运行交付；proof 仅在毒向猎魔人且原生免疫来源被登记时存在。
 * 普通原生毒仍保留 claim 与独立贡献；null proof 不表示没有付款或没有毒来源。
 */
export interface DeliveredDemonPoison {
  readonly proof: object | null;
  readonly claim: Readonly<NightPoisonClaim>;
  readonly lateUnknown: () => boolean;
  readonly sealContribution: () => Readonly<NativePoisonContributions>;
}
const nativeAddMark = StatusMarksComponent.prototype.add;
const delivered = new WeakMap<World, Map<number, Readonly<DeliveredDemonPoison> | null>>();
/**
 * 私有 token 对应的唯一封存账本，绑定原 World 与夜号。贡献在普通伤害清标记前捕获；
 * frozen 只在底层来源冻结成功后置位，后续构造失败也不恢复该 token 的可用性。
 */
interface Sealed {
  world: World;
  day: number;
  poison: Readonly<DeliveredDemonPoison> | null;
  contributions: Readonly<NativePoisonContributions> | null;
  heal: Readonly<DeliveredDemonHeal> | null;
  healContributions: Readonly<NativeHealContributions> | null;
  frozen: boolean;
}
const sealedSources = new WeakMap<object, Sealed>();
const sealedNights = new WeakMap<World, Set<number>>();
/** 本次行动交付结果；used 只区分用药与放弃，poison 不承载救药回执。 */
export interface DemonWitchTurnResult {
  readonly poison: Readonly<DeliveredDemonPoison> | null;
  readonly used: boolean;
}
/** 原有限猎魔人板中唯一原生女巫的执行路径；await 后复验原请求与目标，最终关闭交付窗口。 */
export async function executeDemonWitchTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  wolfTarget: number | null;
  /** 只在原 new 点读取；原 frame 开启／夜复位已发生，依赖不授予用药资格。 */
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort };
}): Promise<Readonly<DemonWitchTurnResult>> {
  const { world, gateway, events, provider, day, wolfTarget } = input,
    frame = openDemonWitchTurnFrame(world);
  if (!frame || frame.day !== day) throw new Error("demon_hunter_native_witch_unavailable");
  const ability = frame.ability as NightAbility<"potion">,
    scope = Object.freeze({});
  let closed = false;
  if (!world.entityIds().every((id) => demonWitchMarksSafe(world, id)))
    throw new Error("demon_hunter_native_marks_invalid");
  // frame 开启和 marks 检查先完成；原 new／bind 在 try 外，失败保留复位前缀，不加新的 finally。
  const request = new input.construction.requestFactory(world, events, day).create({
    phase: Phase.Night,
    actorId: frame.witchId,
    allowedTools: ["use_potion"],
    stage: "witch",
    requiresAction: true,
    summary: { key: "request.summary.night_action" },
    context: {
      ability_id: "native:potion",
      allow_fallback: false,
      action_failure_policy: "error",
      ...(ability.state.heal > 0 ? { wolf_target: wolfTarget } : {}),
    },
  });
  bindDemonWitchRequest(
    world,
    request,
    scope,
    () => !closed && frame.isCurrent(),
    frame.targetCurrent,
  );
  const authorized = () => demonWitchRequestCurrent(world, request);
  try {
    if (!authorized()) throw new Error("demon_hunter_native_witch_revoked");
    const raw = await provider.getAction(request);
    if (!authorized()) throw new Error("demon_hunter_native_witch_revoked");
    const call = readDemonPotionTool(raw);
    if (!call || !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
      throw new Error("demon_hunter_native_witch_invalid");
    const candidateMarks = world.getComponent(call.args.target_id, COMPONENT.StatusMarks);
    if (
      candidateMarks &&
      (!statusMarkSnapshot(candidateMarks, StatusMark.PoisonMark) ||
        Object.getPrototypeOf(candidateMarks) !== StatusMarksComponent.prototype ||
        Object.getOwnPropertyDescriptor(candidateMarks, "has"))
    )
      throw new Error("demon_hunter_native_marks_invalid");
    const checked = gateway.validateAndSanitize(world, frame.witchId, call, {
      phase: Phase.Night,
      day,
      abilityId: "native:potion",
      deferOperation: true,
    });
    if (
      !checked.ok ||
      !checked.sanitizedCall ||
      !authorized() ||
      !demonWitchRequestTargetCurrent(world, request, call.args.target_id)
    )
      throw new Error("demon_hunter_native_witch_invalid");
    const targetId = call.args.target_id,
      potion = call.args.potion_type;
    const source = captureNightLife(world, frame.witchId),
      target = captureNightLife(world, targetId);
    if (!source || !target) throw new Error("demon_hunter_native_witch_revoked");
    Object.freeze(source);
    Object.freeze(target);
    let poison: Readonly<DeliveredDemonPoison> | null = null;
    const native =
      potion === PotionType.Poison && targetId === frame.demonId
        ? captureDemonNativePoison(world, frame.witchId, ability, targetId)
        : null;
    if (potion === PotionType.Poison && targetId === frame.demonId && !native)
      throw new Error("demon_hunter_native_poison_unavailable");
    let marks = world.getComponent(targetId, COMPONENT.StatusMarks);
    if (potion !== PotionType.None && !marks) {
      marks = new StatusMarksComponent();
      world.addComponent(targetId, COMPONENT.StatusMarks, marks);
    }
    const contribution =
      potion === PotionType.Poison && marks
        ? openNativePoisonContribution(world, targetId, marks)
        : null;
    const healContribution =
      potion === PotionType.Heal && marks
        ? openNativeHealContribution(world, targetId, marks)
        : null;
    // 先登记使用、写标记及扣瓶，再由 frame 核对真实库存提交；失败不伪造付款回滚。
    recordNightAbilityUse(ability, day, potion !== PotionType.None);
    if (potion !== PotionType.None) {
      nativeAddMark.call(
        marks!,
        potion === PotionType.Heal ? StatusMark.HealMark : StatusMark.PoisonMark,
      );
      ability.state[potion]--;
      ability.state[potion === PotionType.Heal ? "healUsedThisNight" : "poisonUsedThisNight"] =
        true;
    }
    if (!frame.commit(potion)) throw new Error("demon_hunter_native_witch_commit_failed");
    // frame 已提交后先登记真实贡献；随后 proof、交付或事实发布失败仍保留这段已付前缀。
    if (contribution) commitNativePoisonContribution(contribution);
    if (healContribution) {
      commitNativeHealContribution(healContribution);
      const heals = deliveredHeals.get(world) ?? new Map<number, Readonly<DeliveredDemonHeal>>();
      if (heals.has(day)) throw new Error("demon_hunter_native_witch_delivery_reentry");
      heals.set(
        day,
        Object.freeze({
          claim: Object.freeze({
            source,
            target,
            isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
          }),
          lateUnknown: () => lateUnknownHealContribution(healContribution),
          sealContribution: () => sealNativeHealContribution(healContribution),
        }),
      );
      deliveredHeals.set(world, heals);
    }
    if (native && contribution) {
      const proof = commitDemonNativePoison(native);
      if (!proof) throw new Error("demon_hunter_native_poison_commit_failed");
      poison = Object.freeze({
        proof,
        claim: Object.freeze(
          originalPoisonIntent(
            {
              source,
              target,
              isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
            },
            {
              family: "demon-witch",
              day,
              stage: "witch",
              actorLife: source,
              requestedTargetId: targetId,
              abilityId: "native:potion",
            },
          ),
        ),
        lateUnknown: () => lateUnknownPoisonContribution(contribution),
        sealContribution: () => sealNativePoisonContribution(contribution),
      });
    } else if (potion === PotionType.Poison) {
      // 普通原生毒不持有猎魔人免疫 proof；来源与后续独立毒贡献仍必须保留。
      poison = Object.freeze({
        proof: null,
        claim: Object.freeze(
          originalPoisonIntent(
            {
              source,
              target,
              isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
            },
            {
              family: "demon-witch",
              day,
              stage: "witch",
              actorLife: source,
              requestedTargetId: targetId,
              abilityId: "native:potion",
            },
          ),
        ),
        lateUnknown: () => lateUnknownPoisonContribution(contribution!),
        sealContribution: () => sealNativePoisonContribution(contribution!),
      });
    }
    const nights = delivered.get(world) ?? new Map<number, Readonly<DeliveredDemonPoison> | null>();
    if (nights.has(day)) throw new Error("demon_hunter_native_witch_delivery_reentry");
    nights.set(day, poison);
    delivered.set(world, nights);
    settleRequestDelivery(scope, true);
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId: frame.witchId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    events.push({
      timestamp: Date.now(),
      type: potion === PotionType.None ? "witch_potion_skipped" : "witch_potion_used",
      payload: {
        actorId: frame.witchId,
        targetId,
        potionType: potion,
      },
    } as GameEvent);
    return Object.freeze({ poison, used: potion !== PotionType.None });
  } finally {
    closed = true;
    settleRequestDelivery(scope, false);
  }
}

/** 在普通伤害清除标记前封存原交付贡献；返回仅本控制器登记的运行 token，同夜不得重封。 */
export function sealDeliveredDemonWitchSources(world: World, day: number): object {
  if (
    demonHunterFreezeDay(world) !== day ||
    (demonWitchRequiredThisNight(world) && !delivered.get(world)?.has(day))
  )
    throw new Error("demon_hunter_native_sources_missing");
  const seen = sealedNights.get(world) ?? new Set<number>();
  if (seen.has(day)) throw new Error("demon_hunter_native_sources_already_sealed");
  const poison = delivered.get(world)?.get(day) ?? null;
  const contributions = poison?.sealContribution() ?? null;
  const heal = deliveredHeals.get(world)?.get(day) ?? null,
    healContributions = heal?.sealContribution() ?? null;
  const token = Object.freeze({});
  sealedSources.set(token, {
    world,
    day,
    poison,
    contributions,
    heal,
    healContributions,
    frozen: false,
  });
  seen.add(day);
  sealedNights.set(world, seen);
  return token;
}
/** 冻结后的来源结果；救／毒覆盖只重算本控制器涉及的目标，不替代其它独立来源。 */
export interface DeliveredDemonNightSources extends DemonNightSources {
  readonly poisonOverrides: readonly Readonly<{ targetId: number; poison: boolean }>[];
  readonly healOverrides: readonly Readonly<{ targetId: number; heal: boolean }>[];
}
/**
 * 完整来源只取真实控制器与私有 token，不从 Tape 事实或调用方 metadata 恢复授权。
 * 先查询原来源当前性及迟到的独立贡献，再冻结底层毒／狩猎；底层成功后立即消费封存账本。
 * 猎魔人的原生毒免疫只抵消该原生贡献，unknown 或迟到独立毒继续参与目标的最终覆盖。
 */
export function freezeDeliveredDemonNightSources(
  world: World,
  token: object,
  faultId: string | null = null,
): Readonly<DeliveredDemonNightSources> {
  const sealed = sealedSources.get(token),
    day = demonHunterFreezeDay(world);
  if (!sealed || sealed.world !== world || sealed.day !== day || sealed.frozen)
    throw new Error("demon_hunter_native_sources_invalid");
  const poison = sealed.poison,
    contributions = sealed.contributions;
  const originalSourceCurrent = poison?.claim.isCurrent?.() === true;
  const lateUnknown = poison?.lateUnknown() ?? false;
  const healCurrent = sealed.heal?.claim.isCurrent?.() === true,
    lateHeal = sealed.heal?.lateUnknown() ?? false;
  const result = freezeDemonNightSources(world, poison?.proof ? [poison.proof] : [], faultId);
  sealed.frozen = true;
  const immunity =
    !!poison?.proof &&
    contributions?.native === true &&
    originalSourceCurrent &&
    result.poisonImmunities.length === 1;
  return Object.freeze({
    hunt: result.hunt,
    healOverrides: Object.freeze(
      sealed.heal && sealed.healContributions
        ? [
            Object.freeze({
              targetId: sealed.heal.claim.target.id,
              heal:
                sealed.healContributions.unknown ||
                lateHeal ||
                (sealed.healContributions.native && healCurrent),
            }),
          ]
        : [],
    ),
    poisonImmunities: Object.freeze(immunity ? [...result.poisonImmunities] : []),
    poisonOverrides: Object.freeze(
      poison && contributions
        ? [
            Object.freeze({
              targetId: poison.claim.target.id,
              poison:
                contributions.unknown ||
                lateUnknown ||
                (contributions.native && originalSourceCurrent && !immunity),
            }),
          ]
        : [],
    ),
  });
}

/**
 * 负责有限猎魔人板原生守卫／预言家的严格交付；输入原夜上下文、frame及惰性构造依赖，输出原库存提交与事实。
 * 原体、目标与付款仍由 frame／请求 owner 校验；成功先交付再发事实，提交失败沿原 finally 结算 false。
 * 工厂构造和绑定原在 try 之前，构造抛错不会进入该 finally；不新增清理或替换捕获的原库存／操作。
 */
import {
  Camp,
  Phase,
  StatusMark,
  settleRequestDelivery,
  COMPONENT,
  type StatusMarksComponent,
} from "../../../../core";
import { StatusMarksComponent as Marks } from "../../../../core/domain/components/status_marks";
import { captureNightLife } from "../../../../core/domain/night_effects";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { NightStageContext } from "../../stages/night/contracts";
import { resolveInspection } from "../inspection";
import { recordOwnNightAction } from "../night_action_history";
import { demonNativeNightActor, openDemonNativeNightFrame } from "./authority";
import {
  bindDemonNativeNightRequest,
  demonWitchRequestCurrent,
  demonWitchRequestTargetCurrent,
  readDemonNativeNightTool,
} from "./native_potion_requests";
import { openNativeGuardContribution, commitNativeGuardContribution } from "./guard_contribution";
const nativeAdd = Marks.prototype.add;
/** 仅此有限板的原生预言家／守卫进入该路径；赠予、复制及其他板仍沿各自原机制。 */
export async function executeDemonNativeNight(
  ctx: NightStageContext,
  kind: "seer_check" | "guard",
): Promise<void> {
  const { world } = ctx,
    day = ctx.currentDay(),
    actor = demonNativeNightActor(world, kind);
  if (!actor) return;
  const frame = openDemonNativeNightFrame(world, actor.actorId, actor.ability, kind, day);
  if (!frame) throw new Error("demon_hunter_native_night_unavailable");
  const guard = kind === "guard",
    name = guard ? "guard" : "check_identity",
    scope = Object.freeze({});
  let closed = false,
    committed = false;
  // callee 先于 ctx.events 读取；原构造／绑定处于 try 外，保留失败边界而不补清理。
  const request = new ctx.requestFactory(world, ctx.events, day).create({
    phase: Phase.Night,
    actorId: actor.actorId,
    allowedTools: [name],
    stage: guard ? "guard" : "seer",
    requiresAction: true,
    summary: { key: "request.summary.night_action" },
    context: {
      ability_id: `native:${kind}`,
      allow_fallback: false,
      action_failure_policy: "error",
    },
  });
  bindDemonNativeNightRequest(
    world,
    request,
    scope,
    () => !closed && frame.isCurrent(),
    frame.targetCurrent,
    kind,
  );
  const authorized = () => demonWitchRequestCurrent(world, request);
  try {
    if (!authorized()) throw new Error("demon_hunter_native_night_revoked");
    const raw = await ctx.actionProvider.getAction(request);
    if (!authorized()) throw new Error("demon_hunter_native_night_revoked");
    const call = readDemonNativeNightTool(raw);
    if (
      !call ||
      call.name !== name ||
      (call.args.target_id !== null &&
        !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
    )
      throw new Error("demon_hunter_native_night_invalid");
    const valid = ctx.toolGateway.validateAndSanitize(world, actor.actorId, call, {
      phase: Phase.Night,
      day,
      abilityId: `native:${kind}`,
      deferOperation: true,
    });
    if (
      !authorized() ||
      !valid.ok ||
      !valid.sanitizedCall ||
      (call.args.target_id !== null &&
        !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
    )
      throw new Error("demon_hunter_native_night_invalid");
    const targetId = call.args.target_id;
    if (guard) {
      const target = targetId === null ? null : captureNightLife(world, targetId);
      const marks = targetId === null ? null : world.getComponent(targetId, COMPONENT.StatusMarks);
      if (targetId !== null && (!target || !marks))
        throw new Error("demon_hunter_native_guard_target_invalid");
      const contribution =
        targetId !== null && marks ? openNativeGuardContribution(world, targetId, marks) : null;
      if (!authorized() || !frame.commitGuard(targetId))
        throw new Error("demon_hunter_native_guard_commit_revoked");
      if (targetId !== null && target && marks && contribution) {
        nativeAdd.call(marks, StatusMark.GuardMark);
        commitNativeGuardContribution(contribution);
        (ctx.state.guardClaims ??= []).push({
          target: Object.freeze(target),
          marks,
          isCurrent: frame.sourceCurrent,
          contribution,
        });
      }
      committed = true;
      settleRequestDelivery(scope, true);
      ctx.events.push({
        timestamp: Date.now(),
        type: "guard_applied",
        payload: { actorId: actor.actorId, abstain: targetId === null, targetId },
      });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "guard_applied",
        actorId: actor.actorId,
        phase: Phase.Night,
        status: "ok",
        output: { abstain: targetId === null, target_id: targetId },
      });
      if (targetId !== null)
        recordOwnNightAction(world, actor.actorId, day, "guard", targetId, false);
    } else {
      if (targetId === null) throw new Error("demon_hunter_native_seer_target_invalid");
      const result = resolveInspection(world, targetId, "camp", ctx.roleCatalog);
      if (!result || !authorized() || !frame.commitSeer(targetId, result))
        throw new Error("demon_hunter_native_seer_commit_revoked");
      committed = true;
      settleRequestDelivery(scope, true);
      const isWerewolf = result.camp === Camp.Wolf;
      ctx.state.seerChecks.push({
        seerId: actor.actorId,
        targetId,
        isWerewolf,
        result: { ...result },
      });
      recordOwnNightAction(world, actor.actorId, day, "check", targetId, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "seer_checked",
        payload: { actorId: actor.actorId, targetId, isWerewolf, result: { ...result } },
      });
    }
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId: actor.actorId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
  } finally {
    closed = true;
    if (!committed) settleRequestDelivery(scope, false);
  }
}

/**
 * 负责猎魔板原生女巫毒药的实际消耗证明与首波免疫来源定格。输入为原 World、能力与不透明 token；
 * 输出为当前消耗证明、毒免事实及猎杀结算，原先毒药后猎杀的冻结与拒绝顺序保持。
 * 本模块写自己的 pending／proof／spent 记录，实际库存写与原体资格仍由原女巫／authority 持有；
 * commit 只能复验已真实付款，不消费第二份库存。失效／失败保已消费前缀，不直接写 Alive 或授予新权限。
 */
import { types } from "node:util";
import { Role, WitchSelfHealRule, type World } from "../../../../core";
import {
  demonNativePoisonFrame,
  demonHunterFreezeDay,
  freezeDemonHunt,
  type DemonNativePoisonFrame,
  type DemonHuntSettlement,
} from "./authority";
import {
  DEMON_HUNTER_POLICY,
  demonJson,
  demonSnapshot,
  exactDemonData,
  ownDemonData,
} from "./state-slot";
interface NativePoison {
  world: World;
  frame: Readonly<DemonNativePoisonFrame>;
  ability: object;
  state: object;
  source: object;
  expected: string;
  committed: boolean;
  frozen: boolean;
  proof: object | null;
}
const pending = new WeakMap<object, NativePoison>();
const proofs = new WeakMap<object, NativePoison>();
const spentAbilities = new WeakSet<object>();
const captures = new WeakMap<World, Map<number, object>>();
const abilityKeys = [
  "id",
  "kind",
  "state",
  "source",
  "sourceDisclosed",
  "startsOnDay",
  "maxUses",
  "uses",
  "lastUsedDay",
  "disabled",
] as const;
const stateKeys = [
  "heal",
  "poison",
  "selfHealRule",
  "canSelfHeal",
  "healUsedThisNight",
  "poisonUsedThisNight",
] as const;
/** 原生能力身份由已安装 World 提供；相等 source 元数据不能替代原对象许可。 */
export function captureDemonNativePoison(
  world: World,
  witchId: number,
  ability: object,
  targetId: number,
): object | null {
  const frame = demonNativePoisonFrame(world, witchId, ability, targetId);
  if (!frame || spentAbilities.has(ability) || captures.get(world)?.has(frame.day)) return null;
  try {
    const snapshot = demonSnapshot(ability);
    if (
      !exactDemonData(snapshot, abilityKeys) ||
      snapshot.id !== "native:potion" ||
      snapshot.kind !== "potion" ||
      !exactDemonData(snapshot.source, ["kind", "role"]) ||
      snapshot.source.kind !== "native" ||
      snapshot.source.role !== Role.Witch ||
      snapshot.sourceDisclosed !== true ||
      snapshot.startsOnDay !== 1 ||
      snapshot.maxUses !== null ||
      snapshot.disabled !== false ||
      !exactDemonData(snapshot.state, stateKeys)
    )
      return null;
    const state = snapshot.state;
    if (
      ![0, 1].includes(state.heal as number) ||
      state.poison !== 1 ||
      state.selfHealRule !== WitchSelfHealRule.Disabled ||
      state.canSelfHeal !== false ||
      state.healUsedThisNight !== false ||
      state.poisonUsedThisNight !== false ||
      snapshot.uses !== 1 - (state.heal as number) ||
      (snapshot.lastUsedDay !== null &&
        (!Number.isSafeInteger(snapshot.lastUsedDay) ||
          (snapshot.lastUsedDay as number) < 1 ||
          (snapshot.lastUsedDay as number) >= frame.day)) ||
      (snapshot.uses === 1 && snapshot.lastUsedDay === null)
    )
      return null;
    const expected = JSON.stringify({
      ...snapshot,
      state: { ...state, poison: 0, poisonUsedThisNight: true },
      uses: (snapshot.uses as number) + 1,
      lastUsedDay: frame.day,
    });
    const token = Object.freeze({});
    pending.set(token, {
      world,
      frame,
      ability,
      state: ownDemonData(ability, "state") as object,
      source: ownDemonData(ability, "source") as object,
      expected,
      committed: false,
      frozen: false,
      proof: null,
    });
    const slots = captures.get(world) ?? new Map<number, object>();
    slots.set(frame.day, token);
    captures.set(world, slots);
    return token;
  } catch {
    return null;
  }
}
/** 调用方先完成原合法库存写入；此处只复验并缓存实际消耗，不再次消费库存。 */
export function commitDemonNativePoison(token: object): object | null {
  const p = pending.get(token);
  if (
    !p ||
    p.committed ||
    p.frozen ||
    !p.frame.isCurrent() ||
    ownDemonData(p.ability, "state") !== p.state ||
    ownDemonData(p.ability, "source") !== p.source ||
    demonJson(p.ability) !== p.expected
  )
    return null;
  p.committed = true;
  spentAbilities.add(p.ability);
  p.frame.cacheConsumption();
  const proof = Object.freeze({});
  p.proof = proof;
  proofs.set(proof, p);
  return proof;
}
export interface DemonPoisonImmuneFact {
  readonly policy: typeof DEMON_HUNTER_POLICY;
  readonly actorId: number;
  readonly day: number;
  readonly witchId: number;
}
/** 必须在首波任何 Alive 写入前定格；frozen 先置位，后续拒绝仍保此前缀，成功事实才由原 Object.freeze 冻结。 */
export function freezeDemonNativePoison(proof: object): Readonly<DemonPoisonImmuneFact> | null {
  const p = proofs.get(proof);
  if (!p || p.frozen) throw new Error("demon_hunter_native_poison_proof_unavailable");
  p.frame.assertFreezeOpen();
  p.frozen = true;
  if (
    !p.committed ||
    !p.frame.isCurrent() ||
    ownDemonData(p.ability, "state") !== p.state ||
    ownDemonData(p.ability, "source") !== p.source ||
    demonJson(p.ability) !== p.expected
  )
    return null;
  return Object.freeze({
    policy: DEMON_HUNTER_POLICY,
    actorId: p.frame.actorId,
    day: p.frame.day,
    witchId: p.frame.witchId,
  });
}

export interface DemonNightSources {
  readonly hunt: Readonly<DemonHuntSettlement>;
  readonly poisonImmunities: readonly Readonly<DemonPoisonImmuneFact>[];
}
/** 原顺序先校验全部输入与完整性，再定格原生毒药来源、猎杀来源，调用方随后才写 Alive。 */
export function freezeDemonNightSources(
  world: World,
  sourceProofs: readonly object[],
  faultId: string | null = null,
): Readonly<DemonNightSources> {
  const day = demonHunterFreezeDay(world);
  if (types.isProxy(sourceProofs) || !Array.isArray(sourceProofs) || sourceProofs.length > 1)
    throw new Error("demon_hunter_source_proofs_invalid");
  const descriptors = Object.getOwnPropertyDescriptors(sourceProofs);
  if (
    Reflect.ownKeys(descriptors).some((key) => typeof key !== "string") ||
    Object.keys(descriptors).length !== sourceProofs.length + 1
  )
    throw new Error("demon_hunter_source_proofs_invalid");
  const inputs: object[] = [];
  for (let i = 0; i < sourceProofs.length; i++) {
    const d = descriptors[i],
      value = d && "value" in d ? d.value : null;
    const p =
      value && typeof value === "object" && !types.isProxy(value) ? proofs.get(value) : undefined;
    if (!p || p.world !== world || p.frame.day !== day || p.frozen || !p.committed)
      throw new Error("demon_hunter_source_proofs_invalid");
    inputs.push(value);
  }
  const token = captures.get(world)?.get(day),
    registered = token ? pending.get(token) : undefined;
  const complete = registered?.committed ? [registered.proof] : [];
  if (inputs.length !== complete.length || !inputs.every((proof, i) => proof === complete[i]))
    throw new Error("demon_hunter_source_proofs_incomplete");
  const poisonImmunities = inputs
    .map(freezeDemonNativePoison)
    .filter((fact): fact is Readonly<DemonPoisonImmuneFact> => fact !== null);
  const hunt = freezeDemonHunt(world, faultId);
  return Object.freeze({ hunt, poisonImmunities: Object.freeze(poisonImmunities) });
}
